content.text:
        }
    }

    fn snap_group(&mut self, id: usize) {
        if self.group_stamp[id] != self.txn {
            self.group_stamp[id] = self.txn;
            self.group_snaps.push(GroupSnap { id, quota: self.quota[id], pins: self.pin_in_group[id] });
        }
    }

    pub fn certificate(&self, query: &Query) -> Certificate {
        let totals = [
            self.active as u64,
            self.slots as u64,
            self.total_weight as u64,
            self.pins as u64,
        ];
        let mut groups = Vec::with_capacity(query.groups.len());
        for &id in &query.groups {
            let empty = self.members[id] == 0;
            groups.push([
                id as i64,
                self.members[id],
                self.load[id],
                self.quota[id] as i64,
                self.budget[id] as i64,
                self.fp_size[id],
                if empty { -1 } else { self.g_dom[id] },
                if empty { -1 } else { self.g_cls[id] },
            ]);
        }
        let mut nodes = Vec::with_capacity(query.nodes.len());
        for &id in &query.nodes {
            nodes.push([id as u64, self.usage[id] as u64, self.caps[id] as u64]);
        }
        let mut tasks = Vec::with_capacity(query.tasks.len());
        for &id in &query.tasks {
            let task = &self.task[id];
            tasks.push([
                id as u64,
                task.group as u64,
                task.template as u64,
                task.weight,
                task.class,
                task.pinned as u64,
            ]);
        }
        Certificate { totals, groups, nodes, tasks }
    }

    pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
        if expected != self.revision {
            let certificate = self.certificate(query);
            return Outcome {
                accepted: false,
                revision: self.revision,
                violations: None,
                certificate,
            };
        }
        self.txn = self.txn.wrapping_add(1);
        self.journal.clear();
        self.snaps.clear();
        self.group_snaps.clear();
        // Start-of-transaction protection set: read every value a pin or a
        // quota assignment can compare against before any edit is applied.
        for edit in edits {
            match *edit {
                Edit::Move(id, _)
                | Edit::Bind(id, _)
                | Edit::Weight(id, _)
                | Edit::Class(id, _)
                | Edit::Pin(id, _) => self.snap_task(id),
                Edit::Quota(group, _) => self.snap_group(group),
                Edit::Budget(_, _) | Edit::Cap(_, _) => {}
            }
        }
        for edit in edits {
            self.apply(edit.clone());
        }
        // Pin violations, counted once per protected task.
        let mut violated = 0i64;
        let mut moved_diff: HashMap<usize, i64> = HashMap::new();
        for snap in &self.snaps {
            if !snap.pinned {
                continue;
            }
            let task = &self.task[snap.id];
            let differs = task.group != snap.group
                || task.template != snap.template
                || task.weight != snap.weight
                || task.class != snap.class;
            if differs {
                violated += 1;
                if self.group_stamp[snap.group] == self.txn {
                    *moved_diff.entry(snap.group).or_insert(0i64) += 1;
                }
            }
        }
        for snap in &self.group_snaps {
            if self.quota[snap.id] != snap.quota {
                let protected = snap.pins - moved_diff.get(&snap.id).copied().unwrap_or(0);
                violated += protected;
            }
        }
        let violations = [
            self.overcap as u64,
            self.mixed as u64,
            self.workbad as u64,
            violated as u64,
        ];
        let accepted = violations.iter().all(|&count| count == 0);
        if accepted {
            self.revision += 1;
            self.journal.clear();
        } else {
            self.rollback();
        }
        let certificate = self.certificate(query);
        Outcome { accepted, revision: self.revision, violations: Some(violations), certificate }
    }
}
